mapper.select:
select count(*) from () x
 where 1=1

   and ((x.display_snapshot::jsonb)->>'title' ilike concat('%',#{keyword},'%')
        or (x.display_snapshot::jsonb)->>'knowledgePoint' ilike concat('%',#{keyword},'%'))


   and x.subject_id=#{subjectId}


   and x.knowledge_point_id=#{knowledgePointId}


   and x.completed_at>=#{from}


   and x.completed_at<#{to}

select * from () x
 where 1=1

   and ((x.display_snapshot::jsonb)->>'title' ilike concat('%',#{keyword},'%')
        or (x.display_snapshot::jsonb)->>'knowledgePoint' ilike concat('%',#{keyword},'%'))


   and x.subject_id=#{subjectId}


   and x.knowledge_point_id=#{knowledgePointId}


   and x.completed_at>=#{from}


   and x.completed_at<#{to}

 order by x.completed_at desc,x.task_id desc offset #{offset} limit #{limit}

mapper.sql:
where 1=1

  and regexp_replace(x.presentation_snapshot->>'stem','<[^>]*>','','g') ilike concat('%',#{keyword},'%')


  and upper(x.presentation_snapshot->>'questionType')=#{questionType}


  and upper(x.difficulty_snapshot)=#{difficulty}


  and exists(
      select 1 from jsonb_array_elements(case when jsonb_typeof(x.knowledge_snapshot->'items')='array'
           then x.knowledge_snapshot->'items' else '[]'::jsonb end) k
       where coalesce(k->>'knowledgePointId',k->>'id')=#{knowledgePointId}::text)


  and x.answered_at>=#{from}


  and x.answered_at<#{to}

where s.user_id=#{userId} and s.goal_id=#{goalId}
  and s.session_type in ('self_practice','past_paper_practice')
  and s.status='completed' and s.settled_time is not null

  and s.id=#{sessionId}


  and s.session_type=#{sessionType}


  and s.settled_time>=#{from}


  and s.settled_time<#{to}

where 1=1

  and x.exam_type=#{examType}


  and x.completed_at>=#{from}


  and x.completed_at<#{to}
